from __future__ import annotations

import pytest

from llm_router import Model
from tests.llm_router.support.fault_server import (
    ScriptedHTTPServer,
    ScriptedResponse,
)
from tests.llm_router.support.workers.response_normalization import (
    run_response_normalization_dual_worker,
)
from tests.llm_router.support.workers.retry import (
    google_generate_path,
    google_success_response,
    openai_chat_path,
    openai_success_response,
)

pytestmark = pytest.mark.verification_kind("unit")

_TEXT = "parity-ok"


def _ok(body: bytes) -> ScriptedResponse:
    return ScriptedResponse(
        status_code=200,
        headers={"Content-Type": "application/json"},
        body=body,
    )


@pytest.mark.verifies("REQ_RESPONSE_NORMALIZATION[revision==1]")
def test_public_response_provider_is_plain_string_value() -> None:
    openai_routes = {
        ("POST", openai_chat_path()): [_ok(openai_success_response(text=_TEXT))]
    }
    google_routes = {
        ("POST", google_generate_path(model=Model.GEMINI_FLASH)): [
            _ok(google_success_response(text=_TEXT))
        ]
    }
    with (
        ScriptedHTTPServer(port=0, routes=openai_routes) as openai_server,
        ScriptedHTTPServer(port=0, routes=google_routes) as google_server,
    ):
        openai, google = run_response_normalization_dual_worker(
            openai_server_base_url=openai_server.base_url,
            google_server_base_url=google_server.base_url,
        )
    assert openai.ok is True
    assert google.ok is True
    assert google.output_text == openai.output_text == _TEXT
    assert type(google.provider) is str
    assert google.provider == "google"
    assert type(openai.provider) is str
    assert "Provider." not in openai.provider
    assert "Provider." not in google.provider
